import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.CDU0sSpB.js";const c=JSON.parse('{"title":"数据、备份与恢复","description":"Hearth 的本地数据布局、加密备份、恢复边界和全局停止。","frontmatter":{"title":"数据、备份与恢复","description":"Hearth 的本地数据布局、加密备份、恢复边界和全局停止。","outline":[2,3]},"headers":[],"relativePath":"guide/data.md","filePath":"guide/data.md","lastUpdated":null}'),h={name:"guide/data.md"};function d(l,s,p,n,k,r){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="数据、备份与恢复" tabindex="-1">数据、备份与恢复 <a class="header-anchor" href="#数据、备份与恢复" aria-label="Permalink to &quot;数据、备份与恢复&quot;">​</a></h1><p class="lead">Hearth 的事实源是本地 SQLite 事件日志。界面、统计和通知都从记录重建，因此备份数据库比备份页面状态更重要。</p><h2 id="数据布局" tabindex="-1">数据布局 <a class="header-anchor" href="#数据布局" aria-label="Permalink to &quot;数据布局&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>内容</th><th>是否进入加密备份</th></tr></thead><tbody><tr><td><code>.hearth/hearth.sqlite</code></td><td>任务、运行、审批、效果、记忆、方法、同步与事件</td><td>是</td></tr><tr><td><code>.hearth/model-settings.json</code></td><td>对话模型配置与密钥</td><td>以加密元数据形式包含</td></tr><tr><td><code>.hearth/master.key</code></td><td>本机主密钥</td><td>加密后包含</td></tr><tr><td><code>.hearth/workspaces/</code></td><td>隔离的任务工作区</td><td>否</td></tr><tr><td><code>.hearth/artifacts/</code></td><td>受管产物</td><td>否</td></tr><tr><td><code>.hearth/outbox/</code></td><td>本地发件箱与回执</td><td>否</td></tr><tr><td><code>.hearth/backups/</code></td><td>加密备份归档</td><td>否</td></tr><tr><td><code>.hearth/sources/</code></td><td>来源正文快照</td><td>否</td></tr><tr><td><code>.hearth/device-frames/</code></td><td>桌面观察帧</td><td>否</td></tr><tr><td><code>eval/runs/</code></td><td>第一阶段验收运行与产物</td><td>否</td></tr></tbody></table><h2 id="加密备份" tabindex="-1">加密备份 <a class="header-anchor" href="#加密备份" aria-label="Permalink to &quot;加密备份&quot;">​</a></h2><p>服务端提供加密备份 API。备份口令至少 12 个字符；口令经 scrypt（N=32768、r=8、p=1）派生，归档使用 AES-256-GCM 加密。</p><p>创建备份：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;content-type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">replace-with-a-long-passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span></code></pre></div><p>列出和下载：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -OJ</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/download</span></span></code></pre></div><p>从已保存的归档恢复：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;content-type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">replace-with-a-long-passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span></code></pre></div><p>恢复会先写临时 SQLite，检查 <code>user_version</code>、schema 与 <code>integrity_check</code>，重建投影，再事务复制；失败会回滚。恢复期间调度器停止，成功后如果之前正在运行且没有启用全局停止，会重新启动调度器。</p><div class="warning custom-block"><p class="custom-block-title">数据库可恢复不等于产物可迁移</p><p>备份不包含产物正文、工作区、来源正文、发件箱附件、桌面截图和外部服务数据。恢复后任务可能重新出现，但产物文件仍需单独核对。完整归档请一并复制 <code>.hearth/artifacts/</code>、<code>.hearth/workspaces/</code>、<code>.hearth/sources/</code>、<code>.hearth/outbox/</code> 和 <code>eval/runs/</code>。</p></div><h2 id="全局停止与-kill-switch" tabindex="-1">全局停止与 kill switch <a class="header-anchor" href="#全局停止与-kill-switch" aria-label="Permalink to &quot;全局停止与 kill switch&quot;">​</a></h2><p><code>POST /api/security/kill-switch</code> 启用全局停止后：</p><ul><li>调度器停止，桌面会话冻结。</li><li>等待中的审批被取消，相关任务转为可恢复状态。</li><li>重启服务时调度器不会自动启动。</li><li>安全审计记录这次操作。</li></ul><p>关闭 kill switch 后，调度器不会自动恢复，需要显式调用 <code>POST /api/system/start</code> 或重启服务。</p><h2 id="健康与维护" tabindex="-1">健康与维护 <a class="header-anchor" href="#健康与维护" aria-label="Permalink to &quot;健康与维护&quot;">​</a></h2><ul><li><code>GET /api/health</code>：运行时长、内存、磁盘、schema、任务计数、调度器、审批、kill switch 和最近维护。</li><li><code>GET /api/maintenance</code>：最近一次维护结果。</li><li><code>POST /api/maintenance/run</code>：手动运行维护。</li><li><code>GET /api/diagnostics</code>：下载脱敏诊断，不包含路径、密钥或环境秘密。</li></ul><p>服务启动后每 6 小时自动维护一次。维护会清理过期审批、恢复中断任务、删除过期租约、桌面命令、截图、配对和临时文件，不删除任务、记忆或产物。</p>`,21)])])}const F=i(h,[["render",d]]);export{c as __pageData,F as default};
